quests[91403] = { id = 91403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probable Paralytic", description = "Halazzi says dat de Vilebranch have made a new venom dat para... parliz--makes its victims not move--so they can drag them off to be sacrificed. He says it's frog venom.\n\nI said that doesn't make sense. Frogs are poison, right? Halazzi said frogs are normally poisonous, not venomous. But these have sharp horn bits on them, so maybe they have venom! I didn't know frogs could have venom, did you?\n\nLet's find out if these do--then de Witherbark can make an anti-venom!", progress = "Halazzi says venomous is when dey bite or stab you, and poisonous is when you bite or eat dem! Isn't dat interestin'?", completion = "Look at all de samples you found! De chief will know who can make anti-venom for sure.", objectives = "Collect 8 Venomous Horns from Horned Frogs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91404] = { id = 91404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Vile Venom", description = "De Vilebranch are cookin' up more bad things. You should go to de source and make dem stop!\n\nHalazzi has smelled their venom-mixin' place someplace to de southeast, and he thinks it's more den just frog venom.\n\n...Oh, Halazzi also said to bring back some kind of huge fang. Frogs don't have fangs, though. Well, find it anyway!", progress = "Did you look for de big fang?", completion = "Hey, dat's a spider fang. Dat must have been one huge spider!", objectives = "Kill Venomhexxer Raxxis and find the fang Tobui described.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91405] = { id = 91405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Validating the Venom", description = "This means there are both frog and spider venoms in de mixtures. Halazzi says he senses somebody beseeched Shadra with dat fang. Dey must be a really big spider if their fang is dat big!\n\nHalazzi doesn't like that de Vilebranch had it. I can tell. He's unhappy. His ears get all flat like de wings of a kite.\n\nSo we gotta help out. Take de samples and de fang to de Witherbark Chief. We Witherbark have alchemists dat can brew anti-venoms for both spiders and frogs.", completion = "De Vilebranch are de ones doin' somethin' with Shadra?\n\nCould de spiders be workin' against de Witherbark? This doesn't make sense.", objectives = "Speak to the Witherbark Chief and locate an anti-venom alchemist in the village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91406] = { id = 91406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Far from the Hinterlands", description = "As a Torntusk of de Revantusk tribe, I am cautious of Witherbark because of our history with dem in de Hinterlands. My family moved here because of dem.\n\nThe Witherbark here in Zul'Aman seem to respect us, but de Witherbark I remember in de Hinterlands killed and backstabbed their allies for power.\n\nThey worshipped de spider loa, Shadra.\n\nWhen de Hinterlands's Witherbark temple Shadra'Alor fell, de Witherbark must have fled somewhere. Look around for evidence of Hinterlands Witherbark and of Shadra.", completion = "All de places dey mentioned are right next door to Shadra'Alor! Dey probably worshipped Shadra.\n\nWe can't trust dem. Dey are like de venoms dey use. Dey will poison de rest of de tribe against de Revatusk--against us all!", objectives = "Investigate the Witherbark from the Hinterlands for signs of Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91407] = { id = 91407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of the Loa", description = "I lost friends to venoms made from Shadra's spiders in de Hinterlands. I gotta know if Shadra's lurkin' around here, twistin' de minds of these Witherbark. No Revantusk will be safe in Zul'Aman with Shadra-worshippin' Witherbark around!\n\nMaybe I seem paranoid, but I have my reasons. And you have Halazzi's ear. You could ask him to reveal to you any hidden spiders, yes? I know those long ears can hear dem skitterin'!\n\nThere is a shrine behind me. Stand in front of it and see if he'll grant you a boon.", completion = "De spiders fled? I thought dey would put up more of a fight. And you said dey were small? Hm.\n\nWell, it doesn't matter. Halazzi has set us on this hunt now. We need to see it through.", objectives = "Find evidence of Shadra in the Witherbark Bluffs with Halazzi's aid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91408] = { id = 91408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Shadra", description = "We will untangle dis mess about Witherbark and Vilebranch soon enough. De loa Shadra and her schemes must be our first priority.\n\nI watched the spiders run in terror from you, and somethin' struck me. De spiders are not just running in panic--they're going somewhere... somewhere dey feel safe, and even I can see dem now. \n\nDey are not hiding anymore. Dey are on de run! Our hunt continues.\n\nLet's follow dem.", progress = "Where dis trail leads, we follow.", completion = "Let's hear him out, but keep your hand on your weapon.", objectives = "Follow the spiders to find where they lead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91409] = { id = 91409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreaming of Spiders", description = "There are three relics of Shadra. I only had two. I had de fang in de village and de eye hidden here. Dey musta stolen de fang somehow, then came for de eye!\n\nWe never had de Shell of Shadra--it was lost when we left Shadra'Alor. It's possible de Vilebranch have de shell.\n\nDe fang and de eye should let us talk to Shadra briefly, even if we lack de last ritual relic to summon her.\n\nCome with me. I will show you how.", progress = "De two artifacts should be enough to speak to a vision of Shadra.", completion = "This is de Shadra I remember from Shadra'Alor. She will assist us if we help her.\n\nShe keeps her promises.", objectives = "Attempt the ritual with the fang and eye to speak to Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91410] = { id = 91410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shared Loa", description = "De Witherbark Chief knows many of us came from de Hinterlands with our worship of Shadra'Alor, but believed Shadra was long dead.\n\nWe should let him know how Halazzi helped us to find and restore Shadra, and of Shadra's presence in de Witherbark crypt. He also must learn of de rapport with de Revantusk.\n\nI will stay with Shadra for now. Will you carry de message?", completion = "With Shadra aligned with us against de Vilebranch, we will punish dem grievously for their evil acts.", objectives = "Speak to the Witherbark Chief about Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91411] = { id = 91411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisara Caverns: Deep in Maisara", description = "Shadra has asked dat we recover de third piece of Mixer Jamanga's ritual, de Shell of Shadra. With it, maybe we can bring her back.\n\nShe recognized both de Witherbark and Revantusk as her allies. I felt her approval upon all of us. I believe this is de right choice.\n\nHalazzi set us on dis path, and we each got our roles to see it through. Gather your allies and go into Maisara Caverns! I would expect one of their leaders to hold de shell. Kill dem and take it back.", progress = "I think dat Shadra will honor her word.", completion = "I can't imagine dat was easy. Halazzi must have blessed your hunt.", objectives = "Recover the Shell of Shadra from within Maisara Caverns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91412] = { id = 91412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Venom Queen", description = "It is time to bring Shadra to her proper place as a loa of de Witherbark and Revantusk. She will be small at first, but one day could be great like Halazzi and Nalorakk!\n\nEven a small loa will be a good ally against de Vilebranch venoms. She is de Loa of Spies, and will block their thievery of our people and relics, just as Halazzi hides them in the mists.\n\nHold de Shell of Shadra in de center of de room, and we will call de loa to us!", progress = "This is more than de return of a loa--it is a bridge between tribes.", completion = "This journey has been... eye-opening. \n\nHad you asked me at the start if we would be allies with Shadra, I would have laughed in your face!", objectives = "Follow Mixer Jamanga's ritual to restore Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91413] = { id = 91413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Twilight Oath's End", description = "<The ancient runes on the page seem to twist under your gaze. Their power seems to be rapidly fading.>\n\n<Ve'nari would be interested in this.>", completion = "Salhadaar cheated death to revive Dimensius, and cheated death again by escaping your wrath.\n\n<Ve'nari pauses for a moment.>\n\nA pity he escaped, but the All-Devouring has perished. Thank you.", objectives = "Bring the Mark of the Twilight Oath to Ve'nari in the Oasis on K'aresh.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91417] = { id = 91417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek out Arator", description = "I see that my son is spending his time with the wounded. Do a father a simple favor and see if he could use your assistance.", sourceObjective = "Speak to Arator over by the wounded Vanguard.", completion = "Those people fight so hard for us. We must do all we can to protect them.", sourceObjectiveStatus = "unverified-source-field" }
quests[91419] = { id = 91419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Dominance" }
quests[91420] = { id = 91420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swap Meet", description = "<The mysterious mineral thrums in your hand. Someone in Tazavesh will find a use for this. Look around the Veiled Market for an interested party.>", completion = "<Om'myuz takes a closer look at the ore.>\n\nThat is quite the intriguing rock you've found. I would like to inspect it further, and any others you find. What say you to a trade?\n\nOther Cartel Om members in the Veiled Market may also be interested in trading wares, should you come across them.", objectives = "Bring your discovery to Om'myuz in Tazavesh.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91426] = { id = 91426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The People's Champion", description = "I think we've done all we can for the moment, {name}. Let's return to the muster point.", objectives = "Return to the muster point with Arator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91427] = { id = 91427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mausoloa Desecrations!" }
quests[91429] = { id = 91429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mausoloa Sarcophagi!" }
quests[91430] = { id = 91430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runaway Limbs!" }
quests[91437] = { id = 91437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call for Participants", description = "<You find a scroll in your pocket that was not there before.>\n\nHey, it's Nostwin! You doing anything? No? Come help us do TIME SCIENCE!\n\nEternus can tell you more.\n\nOkay thanks bye!", sourceObjective = "Speak with Eternus at the Infinite Bazaar near Dalaran.", completion = "Excellent timing, {name}. Now the research can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[91438] = { id = 91438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Heroic Worldly Deeds", description = "All across the Broken Isles there are people in need. They search for hope but are hard pressed to find any. You can be that hope.\n\nSeek out those in peril in the Broken Isles and be the champion they so desperately need.\n\nIt is through such acts that legends are made.", completion = "A single heroic act can turn the tide. A single whisper of hope can turn back despair. This is what gives legends their power.", objectives = "Complete 3 world quests in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91439] = { id = 91439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Heroic Invasion Points", description = "The Legion does not fight conventionally. They deceive, manipulate, and undermine their opposition at every turn.\n\nThere are no battle lines against the Legion. They will open rifts at a weak point and then spill out of it sowing death and destruction. When they invade, it is on their terms.\n\nHowever, this strategy is not invincible. Potent champions, able to move and react swiftly, can stop these invasions at their source. Stop the Legion Invasion. Show people that the Legion can be defeated.", completion = "The power you and your artifact possess were able to halt a Legion invasion. But was it you, or the artifact you wield, that is responsible? On that I will require more information.", objectives = "Complete a Legion invasion point in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91440] = { id = 91440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Hero of the Broken Isles", description = "Heroic deeds are a matter of perspective. What may seem trivial to a mighty hero such as you, could mean the world to another.\n\nSeek out those in need and aid them in whatever task they deem important. In doing so your legend will grow.", completion = "Your name is on the minds of the people, and is shared around the fire. The greater your legend becomes, the more powerful your name will be. But does the power of one's name eclipse that of the artifact they wield? This is the burning question.", objectives = "Complete 5 quests in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91441] = { id = 91441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Heroic Greater Invasion Points", description = "Once the Legion has sown confusion and chaos, then they will begin their real assault. Huge invasion rifts will open and the Legion will march forth in great numbers. The defenders, scattered to protect against smaller rifts, will lack sufficient strength anywhere to stop them.\n\nThat is when champions like you are most needed.\n\nSeek out one of the Legion's major invasions and throw everything you have at it. \n\nShow the people that with enough determination you can cancel the apocalypse.", completion = "Just as I predicted. You were able to stop a massive Legion invasion. It was not you, or your artifact that did this. Rather it was the combination of both that won the day.", objectives = "Complete a greater Legion invasion point in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91442] = { id = 91442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eco-Dome Al'dani", description = "We have received word from Ve'nari that the Wastelanders continue to stand in the way of progress on K'aresh. They threaten the most promising eco-dome.\n\nThe restoration directive of K'aresh must not be interrupted.\n\nPut an end to these inefficiencies.", progress = "Have you put an end to their efforts?", completion = "This is a promising beginning to our new relationship with K'aresh.\n\nGood work, outlander.", objectives = "Biergoth wants you to confront Soul-Scribe within Eco-Dome Al'Dani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91443] = { id = 91443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Rare", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare study, so focus on fighting rare opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 4 rare enemies in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91444] = { id = 91444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Elite", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be an elite study, so focus on fighting elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 5 elite enemies in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91445] = { id = 91445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Comprehensive", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a comprehensive study, so feel free to fight whatever you wish so that we can get a baseline understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 75 enemies in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91446] = { id = 91446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Rare Elites", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare elite study, so focus on fighting rare elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill a rare elite enemy in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91447] = { id = 91447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Demonology", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a demonology study, so focus on fighting demonic opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 30 demons in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91448] = { id = 91448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Heroic Terrors of the Broken Isles", description = "It is time to put both you and your artifact to the test.\n\nSeek out a Terror of the Broken Isles and defeat them.\n\nI am certain that, no matter the outcome, you will provide us with much to think about. I will be watching with great interest.", completion = "A fascinating outcome, {name}. This will shed some much needed light on our research.", objectives = "Kill a world boss in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91449] = { id = 91449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Empowerment", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of the empowered enemies in the experimental, fractured timeline. We need to understand how your abilities fare in the face of terrifying change. \n\nAnd remember, this is for the greater good.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 10 empowered enemies in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91450] = { id = 91450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Ready Now", completion = "Already trained for the ring?\n\nWas very fast. Much impress.\n\nWhat is team's name?\n\nNeed name to shout when run into the Pit.\n\nAnd crowd needs name to shout when you beat other teams.\n\nOr if...", objectives = "Return to the Grudge Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91451] = { id = 91451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk Market", description = "<The mysterious plant thrums in your hand. Someone in Tazavesh will know what to do with it. Look around the Veiled Market for an interested party.>", completion = "<Om'mit turns the plant over in his hands.>\n\nA void-infused stalk from a dead wasteland? This is utterly useless to you. In fact, let me take it off your hands in exchange for plants with more... familiar properties.\n\nOther Cartel Om members in the Veiled Market may also be interested in trading wares, should you come across them.", objectives = "Bring your discovery to Om'mit in Tazavesh.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91452] = { id = 91452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Range of Knowledge", description = "I've always dreamed of being a Farstrider--the adventure! The romance! The beauty of nature! When they put out a call for help, I knew I had to join.\n\nCaptain Dawnrunner assigned me to the library initially, but with everything going on, we all have to be flexible.\n\nI don't mind, but I had hoped to collect all the overdue books before being sent on a real assignment. If you find any, would you bring them to the library for me?\n\nAnd feel free to give them a read! There are some interesting volumes!", progress = "It really takes everyone to get through times like these.", completion = "It might seem like a small thing, but the small things add up.", objectives = "Retrieve 3 overdue books from around Farstrider Hold and return them to the library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91454] = { id = 91454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase-Lost Adventurer", description = "Covered in slime and saliva, the journal bears a partial entry of a previous Phase Diver.\n\n<Day 27\n\nUntethered Space is much more vast than I expected, with monsters stronger than I have seen on K'aresh. \n\nThere is a nearby cave I will explore tomorrow. It is brimming with Phase-Altered Essence. This could bode useful for better understanding the ecology out here.>\n\nResearcher Essarae would be very interested in this.", completion = "<Essarae flips to a random page in the journal.>\n\nThis is brimming with knowledge of Untethered Space. I would like to read it further. \n\nThank you for aiding my research.", objectives = "Take the journal to Researcher Essarae in Shan'dorah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91457] = { id = 91457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abundance: Watha'nan Crypts" }
quests[91458] = { id = 91458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Endurance Hunter" }
quests[91459] = { id = 91459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", completion = "That certainly qualifies as high-ranking, {name}! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91460] = { id = 91460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", completion = "That certainly qualifies as high-ranking, {name}! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Heroic difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91461] = { id = 91461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", completion = "That certainly qualifies as high-ranking, {name}! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91462] = { id = 91462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Central Tower", description = "Ranger Asterae is one of our veterinarians. She usually cares for our lynxes, but the mana wyrm molt is too crucial to the health of the forest to go unmonitored.\n\nThe wyrms regulate the flow of magic from the ley lines to the rest of the woods. When the ley lines were disrupted, so was their molting season. It's not so dire as it once was, but they still need help from time to time.\n\nMeet Asterae at the Central Tower. She can tell you more.", completion = "It's a good thing we came. There are more mana wyrms here than usual.", objectives = "Meet Ranger Asterae at the Central Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91463] = { id = 91463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the South Tower", description = "Despite being new to the Farstriders, Taemin has the hardest assignment. Eversong Woods has mostly recovered, but the further south you go, the more dangerous things get.\n\nHe's a capable mage, though. And we need his nose for magic.\n\nWe'll meet you down there once things are wrapped up here. Captain Dawnrunner was going to provide backup. She should be there by now.", completion = "I-I'm not worried. This is what being a Farstrider is all about!", objectives = "Meet Arcanist Taemin at the South Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91464] = { id = 91464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormarion Assault" }
quests[91465] = { id = 91465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormarion Assault" }
quests[91466] = { id = 91466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Green Dragons", description = "Nozdormu and Queen Alexstrasza believe the best path forward is to aid the Green Dragons.\n\nLike the Black Dragons, the Greens lack a true aspect to lead them. \n\nMerithra is currently hosting guests within the Emerald Gardens. Meet with her to see if you can aid her.\n\nI will continue tracking the incarnates and the other dracthyr.", completion = "Thank you for coming, {name}. My guests are eager to see the Emerald Gardens, and I am pleased to host them.\n\nShall we get started?", objectives = "Speak to Merithra at Merithra's Watch in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91467] = { id = 91467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incarnates on the Move", description = "{name}, I thought I'd find you here. I bring word from the other aspects and my scouts.\n\nThe incarnates are on the move. I know not what they're planning, but you should be aware of their actions.", completion = "The incarnates are looking for something. It's imperative we get more of the flights empowered to stop them.", objectives = "Speak with Emberthal to find out about the Incarnates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91475] = { id = 91475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abundance: Abundant Voidburrow" }
quests[91476] = { id = 91476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines", description = "My friend, we've finished working on some new tools to ensure you'll do some real damage to the Shadowguard. Come by and let's sort it out together.", completion = "My friend! Thanks to our informants inside the Manaforge, we've uncovered some technology that can help you bring it down. This translocator has been calibrated to project your soul back here for a few moments, allowing you to access whatever you may need--but be warned. The pull of Omega's energy fields are strong, and will rip your essence back to your body's position in short order. I'm told it's... quite painful. Still, any advantage is a good advantage. Make haste!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91477] = { id = 91477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines II", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91478] = { id = 91478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines III", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91479] = { id = 91479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines IV", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91480] = { id = 91480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines V", description = "We've got one last upgrade to give, my friend. Come by for one last tune-up and we'll make you the strongest you've ever been!", completion = "With this, you are as powerful as our humble band of soundrels can make you. May it serve you well against Dimensius!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91481] = { id = 91481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speed Siphoner", description = "Great work so far! We've finished some tech that should be useful during your assault on the Manaforge.", completion = "Zo'ropo brings you a new weapon. Use this to feed off of the Manaforge's arcane radiation and turn their energies against them.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91482] = { id = 91482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speed Siphoner II", description = "We've found a way to optimize the Speed Siphoner. Come back to HQ and let me give you a boost.", completion = "Twice as fast, twice as stable. Hunt them down.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91483] = { id = 91483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Mainframe", description = "Our saboteurs have made great progress on hacking Omega's security systems; swing by and let me tell you about what we've learned.", completion = "There are consoles inside the Manaforge that keep the flow of energy running smoothly within the facility. We've cracked security on the first set of them, allowing you to turn the tables on enemies near Loom'ithar and Soulbinder Naazindrhi. You'll only be able to use one, but sabotaging them should allow you an edge in battle. Good luck in there.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91484] = { id = 91484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Forgeweaver", description = "We've progressed further in our infiltration of the Manaforge's defenses. Return to HQ and I'll clear you for access.", completion = "We found a weakness in Forgeweaver Araz's engineering bay that should allow you access to another console nearby. Keep up the pressure, and we'll let you know once the whole facility is ours. Happy hunting.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91485] = { id = 91485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Planet", description = "Hero... we're in. We have full control of Manaforge Omega's security. I'll brief you on your next trip back.", completion = "Manaforge Omega's security systems are under our direct control. Thanks to the damage you've done in there, we can get you access to consoles extending all the way to Salhadaar, and whatever lies beyond. We've also ensured you can use every console you come across. That's all I can do for you. Get in there and finish the fight.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91486] = { id = 91486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attuned to the Aether", description = "Hello! I've learned valuable information about how exposure to Omega's manaflow is impacting you - let us discuss back at Shadow Point when you have a moment.", completion = "My research shows that due to the Reshii Wraps' influence on your physical form, the powerful manasurges and reactors inside Omega can be used to your benefit! While this is only a fraction of your power, it seems that arcane enhancements made to your armaments are made ever more powerful while in their vicinity. This warrants further testing...", objectives = "Report to Ba'choso at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91487] = { id = 91487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Team", objectives = "My friend, we have made much progress together in bringing down the Shadowguard. For your sacrifices and efforts, my colleagues and I consider you one of us. Please, take this modified Gearglider as a show of our gratitiude - may it carry you safely to your next mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91489] = { id = 91489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Companion", objectives = "<The purrkin looks at you warmly. For the first time since you've arrived in K'aresh, it seems to actually *enjoy* your attention. As it pushes closer, its soft mew confirms your suspicions - she seems to want to join you. At least for now.>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91490] = { id = 91490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dousing Teldrassil" }
quests[91492] = { id = 91492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tale of Aln'hara's Bloom" }
quests[91493] = { id = 91493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not What I Ordered", description = "<A bite wound wrecks Hathvelion's forearm.>\n\nSnapdragons... cruel creatures made to kill and feed. Their poison moves as you move. The naga bred the perfect pet.\n\nI'm here on a tip from Lyssara Duskmourne. Sunsail Anchorage's shipping routes have been sabotaged by the naga, and those routes converge... here.\n\nI intercepted a few shipments. Could you help me search them? My team is still out in the field, but they should report back soon.", progress = "The blood elves could just use magic to trade. But there's something dependable about a sturdy wooden box.\n\n<Hathvelion thumps the table beside him and smiles.>\n\nPlus, I hear food and drink aren't as tasty after being transported by magic.", completion = "Lyssara's suspicions proved correct. The naga must be collecting arcane magic from sources all around Eversong. We must put a stop to it, immediately.", objectives = "Inspect 5 Intercepted Shipments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91494] = { id = 91494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Elf's Trash, Another Elf's Treasure", description = "The arcane arts are not my specialty. I'm more versed in tangible magic--herbs, mixtures, distillation, topical applications, extraction, suture, painkilling...\n\nRegardless--that wand. To my uneducated eyes, it looks usable. Why don't you test it on the arcana container? Maybe it could help us against the naga. If it's truly broken, no harm done.", progress = "Maybe the wand was too weak for its original owner. Whatever the case, we can try to put it to good use.", completion = "You can just say I had a hunch about that wand.\n\n...although, be careful. It's powered up now. Don't accidentally drop it.", objectives = "Test the Discarded Wand on the Container of Unstable Arcana. Then, empower the wand in Daggerspine Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91495] = { id = 91495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiar Faces in Peril", description = "Fair winds guide your steps. My wish has come true--Eversong flourishes. But like before, evil threatens all that is good.\n\nTwo townsfolk are unaccounted for since the naga arrived: Enith--Goldenmist's most curious apothecary, and Varnis--he's a student visiting from the city. It is my charge to find them.\n\nMy fellow ranger, Vedoran, must still be in the field. I wonder if he's found something important. Will you keep an eye out for him?", progress = "The Farstriders are grateful for your assistance.", completion = "It is a relief to know they are safe and sound. I hope Varnis will be all right. I saw him scamper back, face as white as a ghost, refusing to speak. He gathered his things and left.\n\nThank you, {name}. I hope no other villagers will be tempted to enter the naga's base!", objectives = "Find Apothecary Enith, Apprentice Varnis, and Ranger Vedoran in Daggerspine Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91504] = { id = 91504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Amassing", description = "Well, you heard Numia. She'll have my bow split in two if I don't rest.\n\nRanger Vedoran reported activity at the lighthouse. A swarm of mana wyrms are gathered there, and of course, more naga.\n\nIf that's where the head of the snake lives, chop it off! My rangers Vedoran and Krann'an will accompany you. And take the wand with you. It proved its worth. Powered up, it should pack a punch against whatever you face.", completion = "The lighthouse itself was coming apart due to the increasing arcane energies, both latent and collected. How ominous indeed. I'll deliver a report to Regent Lord Lor'themar straight away.\n\nThanks to you, my rangers and the town are saved. For that, please rest and drink.\n\n...the wand exploded?! I suppose we now know why it was thrown away.\n\nYou know, a bow would never spontaneously combust.", objectives = "Slay Princess Naz'jena in Daggerspine Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91505] = { id = 91505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggers in My Spine", description = "The naga have a history of abusing arcane magic. I bet my boots this is no different--arcane is their lifeblood and source of power. They are clever to operate now while Eversong is besieged by other threats.\n\nSince I became a Farstrider, I have safeguarded Eversong's western coast. My strike team set up watch on Goldenmist's perimeter already. Fortunately, the naga do not seem interested in the town yet, but they are far too close for comfort.\n\nOur course of action is simple: clear them out!", progress = "We can't let the naga get any closer to Goldenmist.", completion = "You've struck fear and death into their water-spawned hearts! Well done.\n\nWe'll keep an eye on their base and prevent them from rebuilding.", objectives = "Slay 12 Daggerspine naga in Daggerspine Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91506] = { id = 91506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tale of the First Shul'ka and the Flame" }
quests[91507] = { id = 91507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tale of Russula" }
quests[91508] = { id = 91508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tale of Rootways and Wardens" }
quests[91509] = { id = 91509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tale of a Stone Falls from the Sky" }
quests[91522] = { id = 91522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Order from Chaos", progress = "Once I record this data point you can return to your busy schedule.", completion = "What an intriguing insight into those events.\n\nI watched them from afar, but it is so much more fascinating to hear the version of the events as you experienced them.\n\nThank you for sharing that.", objectives = "Talk to Moratari and answer her questions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91523] = { id = 91523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Concealed Threat" }
quests[91525] = { id = 91525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head Hunting: Loom'ithar", description = "Our intelligence describes a colossal beast within the Manaforge, responsible for producing the fabric that gives the Shadowguard their very form. Take it down and we'll hinder their ability to produce reinforcements. Oh, and Ba'choso says to bring some of the silk back with you - he may be able to fashion it into something useful.", progress = "Have you procured a sample?", completion = "Its quality is unlike anything I've ever seen! I'll get to work right away. Now, let's discuss your payment.", objectives = "Defeat Loom'ithar within Manaforge Omega on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91526] = { id = 91526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head Hunting: Forgeweaver Araz", description = "My friend, I hope your assault is going well. It's time for you to dispatch the Forgeweaver; using his mastery of technomancy he oversees both the Manaforge's production pipelines... as well as the ritual to return Dimensius to this plane. His workshop will be further in and heavily guarded, but cutting him down should stop their plans of resurrection for good.", progress = "Does the Forgeweaver yet live?", completion = "{name}... I should have seen that coming. His devotion to Dimensius knew no bounds, and he certainly had contingencies in place to make sure the ritual would be completed. We'll have to attack from another angle. We found some debris from his inner sanctum that made its way here - if you have the skill, we can teach you how to use it for your own ends.", objectives = "Defeat Forgeweaver Araz inside Manaforge Omega on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91527] = { id = 91527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head Hunting: The Soul Hunters", description = "Careful in the wastes, my friend. Scouts report that a trio of Demon Hunters are training south of the Manaforge - with one of them exhibiting power like we've never seen. You can avoid their path if you wish, but ignoring them could open you up to being flanked should they decide to engage. I recommend taking them out if you can, as well as providing us some samples of their newfound strength.", completion = "Soul energy like I've never seen it. While we cannot return them to the way they were, I believe you can use these runes to empower yourself even *through* death. Take them with you, and use them wisely.", objectives = "Defeat The Soul Hunters within Manaforge Omega on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91528] = { id = 91528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head Hunting: Horrors of the Forge", description = "By now no doubt you've seen some of the Manaforge's Elite coming to Salhadaar's aid. I'm sending you a list of names now - focus on these targets, and you may uncover spoils to aid your assault.", progress = "Have you eliminated your targets?", completion = "Nicely done, champion. The resources they were hoarding will find a much better home with your companions.", objectives = "Defeat powerful Elite enemies within Manaforge Omega on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91529] = { id = 91529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head Hunting: Nexus-King Salhadaar", description = "The hour of Salhadaar's demise is upon us. While he may posture upon his Voidwing, he grows desperate at the feet of the All-Devouring. The army he commands is not enough for your might - strike him down.", completion = "Though not the end he deserved, we will celebrate his defeat nonetheless. See Zo'ropo to trade for a well-deserved reward. You have my eternal gratitude for deposing him.", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91530] = { id = 91530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Eye to Eye", objectives = "My friend, this little creature arrived at our hideout saying things like 'you killed my father, prepare to die'. We're not exactly privy to everything happening within the Manaforge, but surely you and this... young man can settle it like adults? Ideally away from our headquarters, and while using inside voices? \n\nI'm sure it's all a misunderstanding. Good luck working it out!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91533] = { id = 91533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Leave Behind", description = "Lothraxion deserved to pay for his arrogance with his life. Hieron didn't. Without him, I'd be dead. I know that Maella and Darkglen feel the same way.\n\nHieron's journal, the one you recovered for us, ended up with me. I knew Hieron, but Astre knew him better. The two of them had found a closeness I admired. Astre deserves to hold onto it.\n\nLast I saw Astre, Hieron was tending to their wounds back at Locus Point.\n\nYou were there when Hieron passed. They should know of his heroism and sacrifice.", progress = "I've recovered some since we last parted ways here, but the whispers continue to plague me. They're insidious, torturing me with what I lack, how I've failed. And--\n\nWait. Is that...? Where did you get that?", completion = "<Astre accepts Hieron's journal and the letter with an empty and distant expression.>", objectives = "Deliver Hieron's journal to Riftblade Astre at Locus Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91535] = { id = 91535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Sweet Grave", description = "<Astre spends a long time in silence, thumbing through Hieron's journal.>\n\nKilled on another world, defending a city that didn't want him. There was so much we planned to do. Now...\n\n<Astre trails off, their eyes focusing on the journal's pages.>\n\nOh. The tea recipe that Hieron was telling me about. He was excited for its properties--called it a purgative for the soul. He never had a chance to brew it.\n\nI know it seems stupid, {name}. I just want to taste Hieron's tea. The leaves should be nearby.", progress = "<Astre thumbs through Hieron's journal with a detached expression.>", completion = "I've got the kettle ready.", objectives = "Collect 8 Ghostflower Leaves around the base of Locus Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91536] = { id = 91536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like a Weed", description = "<Astre looks from Hieron's journal to the worn letter. Their expression flickers with anger.>\n\nBlood elves. They were our people until we embraced the Void. In their ignorance, they exiled us. Yet they are happy to ask us to fight their battles for them.\n\nThey say we threaten the Sunwell. The truth is, they are afraid of us.\n\nLet's protect something of actual value. Kill any beasts that threaten those flowers for Hieron's tea. Silvermoon can save itself.", completion = "I'm not exactly sure how this tea is supposed to help. But I trust Hieron's notes.", objectives = "Kill wildlife around Locus Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91537] = { id = 91537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confronting It", description = "I've put the kettle on. I trust you to brew it, if you wouldn't mind. It shouldn't take more than a moment before the tea is ready to drink.\n\nLet me try it first, just in case it's poisonous. I'm the one that asked to try it.", completion = "I thought I could spare myself this pain by pushing it down.\n\nYou barely even know me. But you've already done so much for me. Thank you.", objectives = "Brew the Ghostflower Tea for Astre.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91539] = { id = 91539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Radiant Echo", description = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", objectives = "Bring the Radiant Echo to a Worldsoul Memory, then release it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91541] = { id = 91541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unchecked Emotions", description = "Ren'dorei learn early to check our emotions. That by controlling ourselves, we can control the Void. Otherwise, our unsuppressed feelings can lead us to ruin.\n\nBut I felt just now the powers of facing my feelings head-on. Maybe I could have done it on my own... But the tea, and your aid, made it easier.\n\nWe should share Hieron's recipe with the others. I'll retrieve the kettle you brewed.", completion = "I was never the best at magic, but my cantrips can at least keep tea warm.", objectives = "Meet with Riftblade Astre at the Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91542] = { id = 91542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Town Inside Me", description = "I can't say that drinking the tea is a pleasant experience. But it helps. I want the others to experience that too.\n\nThat Hieron left us with a gift like this is so... him. He was always doing little things like that for others. For me.\n\nShare the tea with the others, then join me at Obscurion Citadel. I know better than to be alone in a place like that.", completion = "So this is where it happened.\n\nI came here simply to mourn. But... there's something else.", objectives = "Serve Ghostflower tea to Umbric, Maella, and Sideras in the Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91543] = { id = 91543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaking Control", description = "This world is violent and dangerous, but it has an order to things. After you and the others took down the domanaar that ran this citadel and its arena, the food chain must have fallen to disarray.\n\nHarrowers swarm the skies and darken the horizon. I worry they'll seek new hunting grounds closer to our settlements if they aren't dealt with.\n\nPoint them out for me and I'll use my grappling hook to pull them to the ground. Hieron's survival gear proves its use when we need it, as always.", progress = "Have they been dealt with?", completion = "Perhaps some new class of beast will grow strong without these flying monsters to hunt them. Let's hope they threaten the domanaar instead of us.", objectives = "Kill flying Harrowers and Siphoids in Obscurion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91544] = { id = 91544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiar Energies", description = "I know that Hieron died here, but I feel echoes of someone else--of a great clash, where Void met Void. Hieron must have crossed blades with someone... something else. Something that's still out there.", completion = "That domanaar is trying to open a portal to Silvermoon! How is this possible?", objectives = "Scry Void Rifts with Riftblade Astre in Obscurion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91545] = { id = 91545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Before", description = "That must be the monster that killed Hieron. It's tearing open a backdoor for the Void's forces to pour into Silvermoon.\n\nThis damn city. I'm not doing this for them.\n\nSignal Umbric. Let's do this. Together.", completion = "A violent alien world can be home, so long as it's got the right people.\n\nI've got mine right here.", objectives = "Kill Notatus the Riftscarred.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91546] = { id = 91546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Be Changed", description = "There is one unresolved matter...\n\n<Astre reaches into their pocket and reveals the worn letter you had unpackaged alongside Hieron's journal. They run their fingers over it with a pensive expression.>\n\nHieron wanted her to have it. She should know what happened to him.\n\nThis is on me. Silvermoon again... Guess I'll see you when I'm back, {name}.", progress = "At least I'm not visiting my parents.", completion = "I'm glad I went through with this. Thanks for coming with me.\n\nLet's get back to the others in the Voidstorm, {name}.", objectives = "Speak to Umbric about meeting with Astre in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91550] = { id = 91550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Game of Silence and Shadow", description = "You're different! That makes you kinda cool... and kinda really suspicious. We wanna see what you're made of!\n\nSo here's the game: we hide, and you try to find us. If you do, well... guess we'll have to train more for next time. But if you don't? Then maybe our parents will finally let us go on our first solo hunt!\n\nThis isn't just a silly game, okay? It's a trial called Silence and Shadow. It's serious. Very, very serious.\n\nAre you ready?", completion = "That monstrous petalwing took him! And we stood there... frozen like fungus! \n\n<Ilomai shakes her head and gathers her resolve.>\n\nWe don't have time to be scared. We move. Now.", objectives = "Find 4 hiding children.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91551] = { id = 91551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-nest-stration", description = "If mom and dad find out, we are going to be stuck on fish gutting duty for the rest of our lives! \n\nThe elders keep telling us that fear is only useful if it sharpens the mind. Right now, we need clarity, not panic.\n\nWe have to get rid of those nests. Maybe if they are gone, we can eventually find the one they took Shao'mal to. And this way, we can finally drive off those stupid birds!\n\nWe're going to find him. Will you help us?", completion = "Great job! Those petalwings might think twice now before settling down in our pla--I mean hunting area!", objectives = "Search 5 Petalwing Nests for Shao'mal in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91552] = { id = 91552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathered Fury", description = "This would have never happened if those stupid petalwings weren't here!\n\nScare them off, chase them, whatever it takes--we just can't let them stay here. If they stay, they'll just keep hurting people. We can't let that happen.", completion = "You did it? Great! That's really great!\n\nWith more of those petalwings gone, we can finally focus on helping Shao'mal!", objectives = "Defeat 8 Lightbloom Petalwings in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91553] = { id = 91553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haranir Never Say Die!", description = "That's the one! The big one! The one that took him!\n\nWe didn't stop it before. But this time, we will. We are haranir. And haranir never back down. Haranir never give up.\n\nWe're bringing him back. And we're ending this. Are you with me?", completion = "Thank you so much for rescuing me... not that I needed it of course. Anyway, you seem to be pretty good yourself. So after talking with everyone, we all agreed to make you a part of our group! \n\nBe proud. This is an honor only few have received, but you've earned every bit. You are officially one of us! Be proud, stand tall, and never give up!", objectives = "Defeat the Behemoth Petalwing in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91555] = { id = 91555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenders of the Vale" }
quests[91556] = { id = 91556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa's Flame", description = "I will have to take what's left of de supplies back on foot.\n\nDe boat... it's no good now. De hull's cracked, and de frame's split. Won't carry another soul across de water.\n\nBut it'll still serve one final purpose.\n\nIt can be his pyre. We will burn it, de weapons, de armor he wore--everything with him.\n\nVengeance is done. Now we let de fire take him to de loa and to his rest.", progress = "Not long now, Tolbani.", completion = "I hope it brings his spirit peace. And mine.", objectives = "Prepare the funeral pyre for Tolbani in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91557] = { id = 91557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to the Molt", description = "Ah, champion! There are so many unique specimens to identify and catalogue here that I can't keep up.\n\nSpeaking of which, Lady Darkglen took time out of her busy schedule and coordinated an expedition to a particularly dangerous region north of here. I trust in her power, but I've not heard from her or her team in a while and am growing concerned. With any luck, they are simply caught up in their own research.\n\nThat being said, would you please find Lady Darkglen in the Molt and check in on her?", completion = "Verigien sent you? Good timing. Our expedition has run into an unforeseen problem.", objectives = "Find Lady Darkglen in the Molt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91558] = { id = 91558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pestilent Petals", description = "A strange pathogenic presence has infected my fellow ren'dorei.\n\nWhen we arrived, I was awestruck by the colorful vibrancy of this decay-filled valley and its many blood-stained flowers. I had hoped to gather some for my collection... to study of course, but this pathogen was living in the same pestilent pools these blood petals thrive in. Are they naturally resilient, or do they have purifying qualities we can harness for a cure?\n\nDear {name}, please, cautiously gather blood petals for my research.", progress = "Did you collect enough yet?", completion = "Absolutely beautiful! I only hope these flowers can provide a clue to cure my brethren.", objectives = "Collect 10 Mature Blood Petals in the Molt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91559] = { id = 91559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Virulent Vermin", description = "The pathogen appears to spread unevenly among the Molt's wildlife.\n\nWhen my fellow ren'dorei were infected, they grew confused and unresponsive. The local fauna appear more resistant. I suspect some of the Molt's denizens have a stronger resistance than others. Perhaps by examining these beasts we can extract elements for a curative elixir.\n\nCould you gather livers from the creatures nearby?", progress = "How goes the hunt? Have you gathered what we need?", completion = "Marvelous. Let us dissect these immediately, before they spoil.", objectives = "Gather 6 Specialized Livers from creatures within the Molt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91560] = { id = 91560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expunging Explorers", description = "Let us hope we are able to concoct a cure from the reagents you acquired.\n\nI have already prepared the base potion, but now we need to carefully mix in the blood petals and livers you procured. With some calculated determination and a bit of luck, we should be able to craft an antidote and administer it to the afflicted ren'dorei scouts nearby.\n\n{name}, assist Blocciniux by mixing in the gathered ingredients.", progress = "Were you successful? Did the antidote work?", completion = "Riftwalker Lorn is dead? This is troubling news. \n\nYou have my gratitude for saving as many of the ren'dorei as you did.", objectives = "Craft an antidote and cure the infected ren'dorei in the Molt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91561] = { id = 91561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodborne Pathogen", description = "The bloodborne pathogen has mutated!\n\nThe ooze-like carriers of this pathogen usually die quickly, but this new variant is stable even without a host. If it escapes from here, it could infect more ren'dorei and spread across Voidstorm, or worse yet, Azeroth. Our entire operation is at risk.\n\nWe must stop this mutated variant before it spreads!", progress = "Have you contained the spread of this deadly pathogen?", completion = "With the mutated pathogen dealt with and the antidote in hand, we should be safe from further outbreaks. Thank you for your assistance, {name}.", objectives = "Destroy the Mutated Pathogen in the Molt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91563] = { id = 91563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halazzi's Hunt", description = "All of these spiders... \n\nThere must be someting dat we are missing. Halazzi knew exactly how to reveal them, though.\n\nGo to Halazzi's temple. I have no doubt that there is more to dis. Seek out his loa speaker.", completion = "Halazzi says he called you here to help. Is dat true, hash'ura?", objectives = "Seek out the Loa Speaker in Halazzi's Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91565] = { id = 91565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: The Grief Spire", description = "You, hero!\n\nVidious here wars with his nemesis, Ziadan, who has brought the most cutthroat, volatile members of the Horde here to fight for her. Murderers and traitors!\n\nThe leaders of the Alliance do not listen to our calls for action and vengeance! We must take matters into our own hands and support Vidious.\n\n<Amari looks you up and down and raises an eyebrow.>\n\nAnd if it is not hatred of the Horde that drives you, consider what valuable information you may glean by helping a powerful domanaar.", completion = "Ah, another {class} of the Alliance. What is it that drives you, I wonder?\n\nI've heard so many sordid tales! Did the Horde butcher your family? Destroy your home? Betray you on the battlefield?\n\nOr are you one of the soft-hearted ones? Here merely for knowledge and power to benefit your home, not vengeance?\n\nIt matters not to me, so long as you fight in my name.", objectives = "Use the portal to the Grief Spire and report to Vidious.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91566] = { id = 91566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: The Hate Spire", description = "Lok'tar ogar, {class}.\n\nThis domanaar, Ziadan, wars her old foe, Vidious, who has brought the most bloodthirsty, vengeful members of the Alliance here to Slayer's Rise to fight in his name.\n\nZiadan now gives the Horde a chance to stand up for our honor. Our leaders may not sanction this conflict, but when have we let anyone keep us from fighting the good fight?\n\nEven if you have no grievance with the Alliance, Ziadan's efforts keep Vidious from turning his eye on Azeroth. Report to her for your orders.", completion = "You. You look ready for a battle.\n\nYour Horde is noble. You fight for honor. For glory. Sometimes, for the joy of it.\n\nYour eternal conflict with the Alliance is delicious. I shall savor it.", objectives = "Use the portal to the Hate Spire and report to Ziadan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91582] = { id = 91582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pruning the Lattice" }
quests[91583] = { id = 91583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: The Bastion of Valor", description = "Ziadan recently added your great foes, the Horde, to her ranks. However, it is not your fellow mortals that I see sieging my home.\n\nNo, I see monsters of Voidstorm, twisted and empowered, instead. Something is afoot. Has Ziadan added yet another new force to her army?\n\nGo and fight these monsters. Bring me any clues you find as to the source of their newfound power.", progress = "What have you found?", completion = "Ah, of course! Shadowgraft.\n\nThis metal sends a creature surging with power, driving them into a blind, violent frenzy. It cannot be removed without killing the beasts.", objectives = "Collect 12 Spiteful Shadowgraft from wild creatures in the Bastion of Valor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91585] = { id = 91585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh from the Garden", description = "Age has caught up with me this morning and I have pulled something. \n\n<Yu'relen clutches his back.>\n\nStill, our village meal must be prepared. Otherwise, it will mean the loss of much more than just an empty stomach.\n\nIf you would gather some ingredients for the meal, your aid would not go unappreciated.", progress = "I hope you brought back a good harvest.", completion = "Excellent. Even an old cook can work wonders with good hands beside him.", objectives = "Collect 6 Frillfish Fillet and 4 Root Drift Jelly in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91586] = { id = 91586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soil-Based Alternatives", description = "This meal is more than tradition--it is a promise.\n\nThe haranir, rutaani, and fungarians share no love, but in Har'mara they share this table. To honor that pact, each must be fed in their own way. That is what this meal means.\n\nFor the rutaani, they will need nutrient-rich soil as they draw sustenance through their roots. A few bags of it should do.", progress = "I hope you bring news of good soil.", completion = "Good. The rutaani will accept this without complaint. Peace rests on gestures such as these.", objectives = "Collect 6 Nutrient-Rich Soil in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91587] = { id = 91587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carcass Cuisine", description = "The fungarians are caretakers of decay, transforming death into life's renewal. \n\nThey require a sporeglider carcass to sustain their vast community. There is one--larger than most--that has taken to warding off the root drifters we need to sustain our village.\n\nIts end will feed many, and ease our burden. Balance, in more ways than one.", progress = "Did you bring the rind?", completion = "This carcass breathes new sustenance into the fungarians and the peace we uphold.", objectives = "Defeat the Sporeglider Bloomterror in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91588] = { id = 91588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harandar's Kitchen", description = "Now comes the true work: preparing what's been gathered. \n\nThe vegetables must be washed, the bones removed, and the fish roasted. A shared meal is only worthy if made with care. Only then may the meal carry the weight of peace.", progress = "How is the preparation coming along?", completion = "All is ready. Let those who share in this meal remember that unity is not ease--it is effort.", objectives = "Prepare and cook the meal in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91589] = { id = 91589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root Dash Delivery", description = "It's simple fare, but made with care and meaning. Please, take it to the gathering place. I am sure the villagers will show up when the food comes.\n\nDespite the simplicity, if it brings quiet among them, it has done its part.", progress = "Once the meal is set, our job will be done for today.", completion = "You have done more than fill bowls--you have upheld something fragile and vital. For the peace of Har'mara, we thank you.", objectives = "Set up the communal meal in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91590] = { id = 91590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Concealed Threat" }
quests[91591] = { id = 91591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Concealed Threat" }
