quests[91596] = { id = 91596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Endurance Hunter" }
quests[91597] = { id = 91597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: For My Alliance", description = "My bastion is besieged by Ziadan once more!\n\nYou Alliance have proven to me you are strong. I am eager to see you in action upon the battlefield. \n\nMy own forces could use a taste of your courage. Take this Voidclarion and embolden the void underlings that fight for me. Let them know they have your backing. Let them feel the glory of your Alliance!", completion = "Excellent. The battle is only truly balanced when it tips toward my favor.", objectives = "Empower 8 Griefbound forces at the Bastion of Valor in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91598] = { id = 91598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Pre-Provoked Violence", description = "So, Ziadan would stoop so low as to use shadowgraft? Can she not adequately stir the bloodlust of her Horde minions? She's lost her touch.\n\nI need no such army to overpower her. I have you.\n\nShow her how it's done. Decimate her forces before they reach beyond the bounds of Slayer's Rise. They could threaten your precious mission here, after all.", completion = "What?! If Ziadan is also besieged by shadowgrafted creatures, that means...\n\nAn interloper.", objectives = "Slay Void creatures or players in the Bastion of Might in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91599] = { id = 91599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: A Familiar Grudge", description = "It is time to take the fight to Ziadan.\n\nShe undoubtedly has her own favorite pet--someone from your world who takes this conflict personally. She is particularly fond of the flavors of rage.\n\nI prefer aching, heart-wrenching grief, myself, and we shall prove which fuels you mortals with greater strength.\n\nAmong their forces is a dark warlock that has slain many of your kind. I've tasted their rage in the air.\n\nGo. Savor the fight.", completion = "Very good. The Horde is filled with such hateful, violent souls.", objectives = "Slay Manus Deathwake at the Bastion of Might in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91600] = { id = 91600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Setting It Aside", description = "I knew shadowgrafting was beneath Ziadan. I would not spend eons locked in conflict with one so uncouth.\n\nTherefore, our little game has an uninvited guest. Not you, of course. We love watching you kill for us.\n\nTo the far north is the Voidscar Arena. The last time another domanaar tried to come between us, they built that citadel. It has laid empty for ages.\n\nIf another domanaar intends to challenge us, they will have staged their forces there.", completion = "Who is our enemy, then? Who seeks to rise and claim more power while Xal'atath's back is turned?\n\nTenebre? Chrysalius? Decimus?", objectives = "Meet the domanaar at the Voidscar Arena in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91601] = { id = 91601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Apex Predator" }
quests[91602] = { id = 91602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Apex Predator" }
quests[91603] = { id = 91603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Two Against One", description = "You. Alliance weakling.\n\nShadowgraft requires a potent font to power it--likely more than one, given this many creatures. They will be nearby. Destroy the power sources, then meet us on the next ridge.\n\nRemember: if this domanaar succeeds, their conquest will not end in Slayer's Rise. They will find a way to your homeworld. They would shadowgraft Azeroth herself. Put an end to this.\n\nMeanwhile, I suppose I shall relish in this opportunity to observe Vidious's weaknesses up close.", completion = "This will prevent further spread of the grafting. However, we must still deal with what remains ourselves. \n\nHow troublesome.", objectives = "Drain the Shadowgraft Graftnodes atop the Voidscar Arena in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91604] = { id = 91604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Apex Predator" }
quests[91605] = { id = 91605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: The Wrong Side", description = "Indeed, the Voidscar Arena is crawling with Void once again. A domanaar rules here, I have no doubt.\n\nThey have not yet emerged to parlay. Our mysterious interloper must not be present. That is well.\n\nLet's have you put an end to this charade. Destroy their forces. Destroy their resources. And turn their tools against them. Make them feel the disdain I feel for them.\n\nZiadan and I shall investigate this interloper.", completion = "We shall find glory in a battle yet.", objectives = "Slay 12 Spiteful monsters, use 4 Graftshaper Tools, and destroy 6 Shadowgraft Energy Containers near the top of Voidscar Arena in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91606] = { id = 91606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Clearing House", description = "A waste of a great monstrosity. Imagine its cunning were it not frenzied! It would have made a fine addition to my collection.\n\nThe shadowgrafting must end. I doubt this domanaar is doing the work himself. There must be a grafter nearby. \n\nWhile Ziadan and I weaken this monster, find and slay the grafter. Then these shadowgrafted monsters will never breach your precious world.\n\nIf nothing else, that will finally draw out our enemy.", completion = "Charonus. Weak. Fickle. One of the first domanaar to bow to Xal'atath. \n\nUnsurprising. Still, let's hear if his offer is of any interest. Premature murder is so boring.", objectives = "Slay Trelus the Grafter at the top of the Voidscar Arena in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91612] = { id = 91612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research" }
quests[91613] = { id = 91613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research Promotion: Timely Assistant", objectives = "{name}, you have been an excellent assistant with our research. I think you deserve a promotion.\n\nFrom now on, you will be able to take on more research assignments simultaneously.\n\nIt's ironic, isn't it, that we never seem to have enough time. Make good use of your time here. Don't make me regret granting you this power.This quest line will unlock:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91614] = { id = 91614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Focusing the Energies", description = "In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln.\n\nThis rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.", completion = "Excellent, Archdruid. These will do nicely.", objectives = "Collect 3 Blood of Sargeras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91615] = { id = 91615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thirst For Blood", objectives = "At last, I have enough Blood of Sargeras to fuel my creations! You will see, Deathlord, what my genius is truly capable of creating...\n\nNow, I must ask that you leave me to my work... there is much to do, and we have little time to waste!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91616] = { id = 91616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Required Reagents", description = "The Sentinels know of a trusted and talented enchanter who specializes in enchantments that affect demons.\n\nShe provides her services for free to the Sentinels, but she does require specific reagents to perform her enchantments.", completion = "This should do.", objectives = "Collect the required crafting reagents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91618] = { id = 91618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Things First", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", progress = "I doubt you'll have a problem getting the leystone, but the sapphire might be a bit harder to acquire.", completion = "You got them! Now to upgrade your barding.\n\nNever say a blacksmith can't improve on a leatherworker's work, I always say. I mean never. I mean... well you know what I mean.", objectives = "Obtain 1 Leystone Ore and a Suramarian Sapphire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91619] = { id = 91619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of Sargeras", description = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras.\n\nWe will need a plentiful quantity. Bring me whatever you can muster.", completion = "Yes, this is just what we need to complete our preparations. These must have been difficult to come by. Thank you, Highlord.", objectives = "Collect Blood of Sargeras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91620] = { id = 91620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggenfogger's Reasonable Request", description = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible.\n\nMarin's asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he's simply returning the favor.\n\nOf course, if you would rather, I can eliminate him.", completion = "No hard feelings, right? Business is business, baby, and business is good. I saw an opportunity and I took it, just like you.\n\nTo show my continued allegiance with your little organization, and as a gesture of goodwill, here's a little sample of the product. It's magic. Bottoms up!", objectives = "Collect Aethril.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91621] = { id = 91621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste For Blood", objectives = "<Ma'haat the Indomitable guzzles the Blood of Sargeras down his throat as he speaks.>\n\nYesh... thish ish... just what I wanted. The egg ish... yoursh!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91624] = { id = 91624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark of Starlight", description = "A vision of starlight permeates your mind.\n\nCustodian Khubon might have more information regarding these Fractured Sparks of Starlight.", completion = "This is a fractured spark of starlight.\n\nEvery week, one of these fragments will appear while on your adventures. In its current state it's rather useless, but combining it with another fragment will grant it power. Reagents like these are malleable, robust, and the prize for many crafters.\n\nCombining two of these fractured fragments will create a unique crafting material that can help an item achieve expertise beyond that of mortal ability.", objectives = "Speak to Custodian Khubon in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91627] = { id = 91627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltheril's Haven", description = "{name}, I presume? Very good. Your reputation precedes you.\n\nLord Saltheril sends his most sincere greetings, along with a cordial invitation to join him at his estate south of Silvermoon.\n\nA portion of the grounds have been carved out as a decadent haven for those seeking refined company and pleasant conversation. He believes you would bring a... unique perspective.\n\n<He looks you over with a hint of polite disdain.>\n\nReceiving an invitation is a rare honor. His lordship hopes you will accept.", completion = "Ah, {name}. Welcome to my Haven--a sanctuary from the world's turmoil since the days of Anasterian.\n\nSome presume this to be merely a frivolous party, but on these beautiful gilded grounds, decisions have been made over wine that have shaped the fates of entire generations.", objectives = "Speak to Lord Saltheril at Saltheril's Haven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91628] = { id = 91628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honored Guests", description = "I am pleased you could join us. Today marks the start of a very special occasion.\n\nThe sin'dorei are no strangers to the war table, but its aristocracy prefers to play more coy. In wartime, the crown sends representatives to curry favor with the nobles. If they are pleased, they might lend gold to the war effort.\n\nIt is very much like courting a lover, with all the jealous games you might imagine.\n\nSo let us play the game, shall we? Deliver these invitations while we finish preparations here.", progress = "Your presence is already turning heads. This will be quite the spectacle.", completion = "Ah, so the rumors are true about your efficiency.\n\nExcellent. Now we can begin the game.", objectives = "Deliver Lord Saltheril's invitations to the Magisters, Blood Knights, Farstriders, and \"traders\" in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91629] = { id = 91629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Esteem", description = "Invitations to my Haven are highly exclusive, especially at a time like this. Extending an offer, even a temporary one, is a great honor.\n\nMy favor carries quite a bit of weight amongst the aristocracy. If I invite an ally of one of our representatives, it suggests I think highly of them--and if I think highly of them, so too will our noble guests.\n\nBut is it not terribly fun if I let you choose an invitation instead?\n\nGo peruse any enticements they may offer, then make your selection.", progress = "Pick any invitation you desire.", completion = "I will have my valet send for them at once.", objectives = "Visit the vendors at Saltheril's Soiree, then choose an ally of the Magisters, Blood Knights, Farstriders, or Shades of the Row to invite to Saltheril's Soiree this week.\n\nYour choice will determine which faction will offer \"Fortify the Runestones\" to your Warband this week.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91630] = { id = 91630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Sight", description = "I can explain, I swear it!\n\nI concealed my knowledge of Shadra before because so many people assume she is an evil force. Our lady is merciless, but only to her enemies. \n\nWhen de Witherbark left de Hinterlands, we had to leave our temple of Shadra'Alor. I brought two of her relics with me: de eye and de fang.\n\nDe Vilebranch stole de fang. Dey are near where I hid the Eye of Shadra, collectin' venom from her children! Please kill de Vilebranch trespassing in the crypt. We can't let dem find de eye.", progress = "I can understand why dey want de venom, but de artifacts are just for communin' with Shadra. What would dey need with them?", completion = "They must mean to weaken us and our ability to commune with Shadra.", objectives = "Defeat the Vilebranch leading the attack on Shadra's children and recover the Eye of Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91631] = { id = 91631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epoch Progress", objectives = "Your power grows stronger, {name}.\n\nPlease, take this token of our gratitude for your assistance with our research. Let it echo with every you that exists in the fractures of this timeline.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91632] = { id = 91632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of an Epoch Journey", objectives = "You have reached your full potential, {name}. Or have you? Perhaps this is only the beginning of your journey through this epoch.\n\nPlease, take this token of our gratitude for your assistance with our research. Let it echo with every you that exists in the fractures of this timeline.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91639] = { id = 91639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Embrace Your Own Legend", description = "I will keep a close eye on your progress and watch your exploits with that artifact unfold with great interest.\n\nOnce you have embraced the power of your own legend, I would like to hear your perspective on how important the artifact you wield has been on your journey.", progress = "We are on a journey of learning and discovery. Let us walk it together.", completion = "You have grown stronger, but your artifact is stronger yet.\n\nIt would appear that my hypothesis holds true--artifacts appear to be the key to protecting Azeroth.", objectives = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have embraced your own legend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91691] = { id = 91691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vanishing of Iridikron", description = "As you traveled through Zaralek caverns, Chronormu and I confronted Iridikron and the Infinite Dragonflight.\n\nWhile we defeated the Infinite Dragonflight's champion, Chrono-Lord Deios, I fear Iridikron escaped.\n\nAllow me to show you what happened, for it gives us a clue of what must be done next.", completion = "What Iridikron plans to do with that artifact is beyond my vision.\n\nWe must focus on Vyrakk and Vyranoth for now.", objectives = "See Nozdormu's vision of the conflict with Iridikron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91693] = { id = 91693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Subtle Game", description = "Appearances are everything. If the court sees that I favor a certain group, they will follow suit.\n\nTake these tokens of my favor and hand them out to our honored guests as you see fit. I suspect they may invite you to partake in their plans and share in the profits, if you choose to align yourself with their cause.", completion = "Splendid.\n\nI dearly hope you find some time to enjoy yourself while court is in season. While I do appreciate the sullen, results-driven sort, you could stand to smile.", objectives = "Hand out 3 tokens of Saltheril's Favor to the factions you wish to aid this week.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91694] = { id = 91694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Breaking the Triad", description = "That glint in your eye! You've already identified me as an enemy and are thinking about how to slay me, yes? Good. \n\nI sent my forces to Ziadan and Vidious's bastions to overthrow them. Then, Xal'atath's bidding pulled me away and I missed all the action.\n\nFortunately, you are here now. You seem like even greater entertainment than watching these two smitten fools refuse to actually end one another.\n\nCome, then! I will prepare my arena and we will put on a real show! Slay me, if you can!", completion = "What did Charonus bolster their army with? Azerothian captives? Figures. \n\nHe only would have taken the most bloodthirsty he could find, if that knowledge helps you sleep at night.\n\nGood work. Charonus will come between Vidious and I no longer.\n\nYou have been helpful. I will ensure you benefit from this aid rendered.", objectives = "Enter the Voidscar Arena and defeat Charonus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91695] = { id = 91695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Down Incarnates", description = "We must turn our attention to Fyrakk and Vyranoth with Iridikron seemingly vanished from our sight.\n\nMerithra and the Green Dragonflight have been pursuing him and have a lead. \n\nThey've received the aid of Shandris Feathermoon in this task.\n\nShe awaits you within Valdrakken. Shandris will need your help with what is to come.", completion = "Ah, {name}. I was about to send a messenger to find you.\n\nI suppose this is Nozdormu's doing. The Bronze Dragonflight do tend to be proactive.\n\nLet's get started.", objectives = "Find Shandris Feathermoon within Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91700] = { id = 91700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Unmade", description = "The void energies concentrated in this citadel have given rise of numerous aberrant creatures.\n\nWildlife mutated by residual energy and horrors originating from beyond the anomalies, continue to feed and draw upon the energies here. It is most unpleasant!\n\nTo safeguard my future enterprises, these threats must be neutralized.", progress = "Have you eliminated the threats?", completion = "I feel much safer knowing those threats have been eliminated.", objectives = "Eliminated 2 Rare creatures in the Stormarion Citadel and surrounding area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91721] = { id = 91721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surpass Your Own Legend", description = "While artifacts are key, we must not dismiss the power of the individuals who wield them.\n\nContinue in your fight against the Legion. Grow strong, stronger than you ever thought possible.\n\nThen we will compare the might of your legend against that of the artifact.", progress = "The person wielding an artifact is of some importance. But how much? Which legend is the greater?\n\nLet us find out together.", completion = "I admit. I am pleasantly surprised to be proven wrong. Your power has grown and I cannot say with certainty which is the greater. You, or the weapon you wield.", objectives = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have surpassed your own legend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91722] = { id = 91722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shape a New Legend", description = "It is clear now that the person is at least as important as the artifact they wield.\n\nPerhaps it is the quality of mortality that diminishes the importance of the individual through the lens of history. While an artifact is eternal, the people wielding them are fleeting.\n\nBut no flame that burns brightly burns forever.\n\nI want you to burn as brightly as you can. Empower your artifact and carve a new legend into the world for all to see.", progress = "An artifact cannot empower itself. Its power grows only when its wielder performs great deeds with it.", completion = "Humbling.\n\nIt is the very nature of finite existence that is the answer.\n\nMortality is the flame that shines brightest because it is free to choose a single moment of glory, rather than be burdened by the weight of eternity.\n\nChoose your moment well, {name}, and nothing, not even time, will be able to stop you.", objectives = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have shaped a new legend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91726] = { id = 91726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstoppable Force", description = "This statue seems out of place here. Nothing else like it. But this is where Anduin Lothar fell against Orgrim Doomhammer at the Battle of Blackrock Mountain.\n\nMany fought on this field. Many didn't make it. Lothar... \n\nLet me tell ye what happened all those years ago.", progress = "It was such a dark day, {name}. Painful to remember.", completion = "It's a tragic story, but maybe something better can be made o' it with those fragments of Turalyon's shield.\n\nPerhaps it can be restored--along with our friend.", objectives = "Ask Kurdran about the events of that day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91728] = { id = 91728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suramar Liberated", completion = "Very intriguing.\n\nI will, of course, record that as a data point.\n\nKnowing how you decide on a course of action will inform further hypothesis.", objectives = "Talk to Moratari and answer her question.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91729] = { id = 91729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armies Gathered", completion = "Fresh insights are invaluable in our efforts here, {name}.\n\nThank you for sharing yours.", objectives = "Talk to Moratari and answer her question.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91730] = { id = 91730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroth Saved", completion = "Too many histories are written about the WHAT, the WHY, the HOW, and the WHEN. Other than names, however, we so rarely get to truly know the WHO.", objectives = "Talk to Moratari and answer her question.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91731] = { id = 91731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midsummer Test" }
quests[91739] = { id = 91739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endeavor Reward" }
quests[91747] = { id = 91747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Quite Nalorakk", description = "Were you the one we saw enter Nalorakk's temple with Zul'jarra?\n\nI thought so! Zul'jarra spoke to him, didn't she?\n\n<Furgh growls in an unsettling way from deep in his throat.>\n\nThat doesn't make sense. The new Voice of Nalorakk says Nalorakk won't speak to anyone but him.\n\nHe gave some of the tribe trinkets to feel closer to Nalorakk. But the tribe now fights over them. The ursas think it's unfair they don't get any. But the chosen cling to them.\n\nWe must take them before more blood is spilled.", progress = "I don't want them. We'll toss them on the fire.", completion = "I think the trinkets were corrupted too.\n\nI'm glad the trinkets are out of my tribe's claws.", objectives = "Remove 8 Nalorakk Trinkets from the furbolgs in Spiritpaw Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91748] = { id = 91748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Much Twilight", description = "This big bear called himself the Voice of Nalorakk and has \"chosen\" some of our tribe as his favorites. He doesn't know, but I saw him put dark, glowing lodestones in the totems around the village to give his chosen power.\n\nDark power radiates from them. The power smells wrong. Not like Nalorakk.\n\nOur guardian bears get agitated and upset near them. They can smell it too!\n\nWe must cleanse the camp. Get rid of those totems!", completion = "I don't know what this fake bear is planning.\n\nBut it's better that his lodestones are destroyed.", objectives = "Destroy 4 corrupted totems in Spiritpaw Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91749] = { id = 91749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Just Not Right", description = "If Chief Groffa is leading the tribe into the dark, he needs to be stopped. The Voice of Nalorakk dazzled Groffa with trinkets. He keeps them locked away so no one else can have them.\n\nIf that is true, he's corrupted too. Even more than the others!\n\nStop him and get the gifts out of the village.", progress = "What is he hoarding in his camp?", completion = "<Furgh licks his chops. They are wet with drool.>\n\nThe bag feels... tempting. I don't like it!\n\nGood he kept this away from others, but also very bad for him.", objectives = "Stop the Chief and recover the false gifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91750] = { id = 91750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perils of Trust", description = "That was scary. We nearly lost Furgh!\n\n<Fleeg's fur twitches in fear and worry as he looks Furgh over.>\n\nFurgh said he heard the Voice of Nalorakk talking to him after touching the treasures.\n\nBut it can't be Nalorakk's voice. Nalorakk doesn't need trinkets!\n\nRip out the throat of this evil that dares to say it speaks for Nalorakk!", progress = "<Fleeg howls mournfully.>\n\nKill them for what they did to Furgh!", completion = "It was a Twilight's Blade monster!\n\nI hope Furgh and the others will be okay now that it is dead.", objectives = "Kill the false Voice of Nalorakk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91757] = { id = 91757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Until Our Next Hello", description = "Well, the moment is fast approaching now.\n\n<Moratari subtly nods in the direction of the raging temporal storm overhead.>\n\nYou would think after so many goodbyes I would be better at this, but alas, I simply prefer hello over goodbye. I know a lot of people around here are going to miss you too.\n\nYou should go say goodbye to them while there is still time.", completion = "There. That was not so bad after all.\n\nThis is not goodbye. It is just a pause until our next hello.\n\nI look forward to it, {name}.", objectives = "Say goodbye to the infinites at the Infinite Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91759] = { id = 91759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Bring That Here" }
quests[91768] = { id = 91768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweating Mana", description = "Default Description", objectives = "Log Description\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91776] = { id = 91776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildhammer and Free" }
quests[91778] = { id = 91778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Deep and Too Dark" }
quests[91779] = { id = 91779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training for Cultists" }
quests[91780] = { id = 91780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethereal Delves", description = "There's even more tae do in delves, {name}! \n\nMeet me in Dornogal. There's loads to discuss!", completion = "Good tae see ye! We've got plenty tae discuss.", objectives = "Meet Brann Bronzebeard within Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91781] = { id = 91781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seasonal Reminder", description = "We're back tae uncovering even more things within delves! \n\nLet's get ye up to speed on what's new first.\n\nAfter that I'll need your help with a wee problem of my own...", completion = "Right, on to that wee problem I mentioned.", objectives = "Learn about Season 3 of Delves from the Delver's Documents, then purchase supplies from Reno Jackson and Sir Finley Mrrgglton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91782] = { id = 91782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repossessed!", description = "I think ye may have guessed what my problem is by now, {name}.\n\nMy clothes, my tools, my curios! Everything but my boots and hat, which I'm nae giving up again.\n\nAll repossessed by some cartel thug who said I was delinquent on my void storage payments, if ye can believe it.\n\nWould ye be willing to help Ol' Brann out of this pickle? I'm sure if ye just explain that this is all some sort of mistake, they'll give back all my hard earned gear.\n\nOr at least me britches.", progress = "Has it always been this breezy in Dornogal?", completion = "I can't believe it was a ruse all along.\n\nA shame about the curios, but at least ye got me britches back!", objectives = "Recover Brann's lost gear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91785] = { id = 91785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ensporcelled" }
quests[91787] = { id = 91787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journey Ends", description = "The Light takes many forms. But I know now what it means to me, and how I want to wield it.\n\nI'm not just a weapon like my father, nor can I devote myself purely to service like Dezco.\n\nBut I can protect people from the evil that threatens them. Right now, that's Xal'atath and her Devouring Host.\n\nWe should return to Lor'themar and do whatever is needed to defeat the Void.\n\nBeyond that, I shall see where protecting others with the Light takes me.", completion = "Thank you, {name}, for bolstering our defenders at the Sunwell.\n\nIt looks like Arator has sorted things out as well, and is ready for whatever may be ahead. It is good to have you both focused on the fight against the Void once more. \n\nArator is a good man. I'm grateful we didn't lose him to this conflict.", objectives = "Return to Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91789] = { id = 91789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apocron" }
quests[91790] = { id = 91790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutallus" }
quests[91791] = { id = 91791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malificus" }
quests[91792] = { id = 91792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Si'vash" }
quests[91795] = { id = 91795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt the Call", description = "We do not know where they intend to strike, but we do know they aim to summon more to their cause.\n\nDestroy the Twilight's Blade before they complete their rituals. We must not let a single champion of the void remain to inspire the new recruits.", progress = "There is much to do. Do not dawdle.", completion = "These champions of the Twilight's Blade are just as foolhardy as the other members of the cult. We will cut them all down, in time.", objectives = "Defeat 3 Twilight's Blade rares in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91796] = { id = 91796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Ours Once More!" }
