quests[91811] = { id = 91811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scorched Mirror" }
quests[91813] = { id = 91813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spiritpaw", description = "I just chased away some furbolg dat were actin' real strange.\n\nDey were arguin' and then one walked toward Lilaju with his hands in de air.\n\nI charged at dem an' scared dem off. Dey are usually hostile and who knows what dey were gonna do?\n\nBut Lilaju wants to see what dey wanted.\n\nOur scouts saw dem follow de river east to de north side of de lake. Track dem down. See what dey want.\n\nIf it's a trick, then kill dem.", completion = "We meant no harm. We wanted to talk about Nalorakk.\n\nA bear showed up that says it speaks for our loa, but it feels wrong.\n\nMaybe with your help, we can sniff out a solution.", objectives = "Find the Spiritpaw furbolg that wanted to speak to Lilaju.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91821] = { id = 91821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Time", description = "There you are, {name}. This timeline is collapsing!\n\nPresumably you have noticed the great rift tearing through reality above us. We don't have much time remaining before we must retreat from this timeline.\n\nTo make matters worse, infernals from other timelines are starting to pour in. Send them back from when they came.", completion = "Hmm, burning that pamphlet produced a very peculiar reaction from the flames.\n\n<Moratari begins taking notes, completely ignoring you.>", objectives = "Slay a Lost Legion Infernal on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91822] = { id = 91822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Regent's Request", description = "Lor'themar has requested our presence. He wasn't exactly forthcoming with the details, but the location he chose speaks volumes.\n\nSilvermoon Harbor. Quiet and out of sight. Not exactly the kind of place one picks for diplomacy or ceremony. No, this feels like something else entirely. Whatever he's planning, it won't be written down in any official record. \n\nCome. Let's find out what the Regent Lord has to say.", progress = "Let's not keep the Regent Lord waiting.", completion = "This should be interesting.", objectives = "Find out what Lor'themar is planning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91823] = { id = 91823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lines Cut, Tongues Silenced", description = "The Twilight's Blade slipped into Tranquillien so easily because they'd stolen knowledge and secrets. About our defenses, our magic, our people. Once inside, they uncovered even more information. \n\nNow they pass that intelligence between themselves using enchanted orbs. Quiet whispers drifting through the dark. Every message tightens the noose around Quel'Thalas.\n\nFind the orbs. Break them. Every shattered crystal is a whisper silenced.", completion = "Well done. The less they know, the safer our people are.", objectives = "Destroy the Communications Orbs in Zeb'tela Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91824] = { id = 91824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thieves' Trail", description = "From what I can see, it looks like the Twilight's Blade stole several arcane artifacts used by our Magisters to enhance long-distance communication. If they learn to wield them, they'll cast their reach far beyond what we can contain. They might even be able to hear our communications... and we can't have that.\n\nRecover the artifacts. If anyone gets in your way... you know what to do.", progress = "Those artifacts should never have fallen into the wrong hands.", completion = "Good. With these back where they belong, their reach just got a lot shorter. I only wish we'd uncovered who took them originally.", objectives = "Recover Quel'dorei Artifacts from the Twilight's Blade in Zeb'tela Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91825] = { id = 91825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Men Keep No Secrets", description = "From what I've seen, this group isn't acting without direction. There's someone leading them, a man hiding in one of their structures.\n\nIf I had to guess, he's the one holding whatever they considered too important to trust to crystal or courier. Documents, plans, names.\n\nFind him, silence him, and bring back whatever he was protecting.", progress = "You made that look easy.", completion = "Excellent. All of their most important secrets, out of their hands.", objectives = "Retrieve the stolen documents from Gareth the Listener in Zeb'tela Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91826] = { id = 91826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tripwire Tango", description = "This cache isn't locked with magic. It's craftsmanship. I can hear the mechanism ticking inside. Tiny cogwheels, tension springs, and probably a poison vial ready to shatter the moment someone tries to pick the lock.\n\nWe'll have to do this together. I'll take the pins, you keep the mechanism from snapping. One wrong move and it'll be enough to drop an ogre in mid-charge. Steady now.", progress = "Easy does it.", completion = "This is vital information. No wonder they went to such lengths to protect it.", objectives = "Disarm the mechanism and retrieve the documents from inside the chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91827] = { id = 91827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Loose Ends", description = "You handled yourself well.\n\nThese documents are too important to pass through couriers or ravens. I'd like you to deliver them personally to Lor'themar. He'll want to see the truth for himself and know who brought it back.\n\nKeep them close, and don't let anyone else near them.", completion = "<Lor'themar examines the documents carefully. After a moment, he looks up at you and allows a faint smile.>\n\nExcellent work. I knew I could count on you both.", objectives = "Return to Lor'themar Theron in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91828] = { id = 91828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for the Lion", description = "A letter arrived for me. No seal, no name. Just folded parchment and handwriting I'd recognize anywhere.\n\nIt didn't say much. He never wastes words. \n\nI've known his family a long time. When they reach out, I answer.", progress = "Yes?", completion = "I've been watching the path. Movement's light, at least for now.", objectives = "Read the letter and assist Valeera Sanguinar in Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91829] = { id = 91829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One by One", description = "Every last cultist is a threat to the people we're trying to save. To Silvermoon itself.\n\nBlasted fanatics with blood on their hands and no intention of letting anyone walk out alive.\n\nWe're already in the camp. Let's make it count. I want them to feel this.", completion = "Clean work. The kind they don't come back from.", objectives = "Kill cultists of the Twilight's Blade at Speaker's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91830] = { id = 91830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepted", description = "The Twilight's Blade hit Tranquillien hard. Slipped in and took all the supplies and information they could ever need, right beneath everyone's nose.\n\nTime to return the favor.\n\nI've marked a few tents. Command posts, messengers' satchels, a supply ledger tucked under a wine crate. That's where they keep their orders, maps, and routes.\n\nGrab everything you can.", progress = "The right scrap of parchment can win a war. Or start one.", completion = "Now this is useful. Let's see how well their little operation runs when they're chasing ghosts and missing crates.", objectives = "Collect 6 Cult Orders from the Twilight's Blade camp at Speaker's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91831] = { id = 91831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keys Are Optional", description = "These people joined the Twilight's Blade looking for purpose, power, or place to belong. For a reprieve from the fear and a promise of certainty.\n\nNow they see it for what it is--a prison dressed up as faith. And they want out.\n\nWe go in together. Get them out before the cult realizes what's happening.", progress = "Ready yourself. This might get messy.", completion = "That should be all of them.", objectives = "Find and release 4 groups of Cult Deserters in Speaker's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91833] = { id = 91833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Deeps", description = "De Vilebranch are sinkin' deeper into their cursed minds. Dey spit in de face of de loa, and believe dey have mastered death.\n\nI could see a certain... someone not likin' dat way of thinkin'.\n\nDey have taken our kin and now dey take our shaman. Meet my scout there and help dem break their plans.\n\nCut de head off de beast and de body will fall.", completion = "Good timing, {race}! These hex masks are wicked powerful.\n\nWhatever VunVun sends our way, we will find a use.", objectives = "Meet the Witherbark Scout at Maisara Deeps.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91834] = { id = 91834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians Must Go", description = "Get rid of shield face and meet me in de hut below.", objectives = "Kill the Dark Hex Guardian and meet me below.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91835] = { id = 91835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send Dem Home", description = "My friend, dis is a mighty gift. Shadra is givin' us a blessin' for de tasks ahead.\n\nThese Vilebranch really are livin' up to their name. Dey drain de spirit from de Witherbark and create undead to serve dem.\n\nWe must free de Witherbark from these necrotic bonds.\n\nMy friend's still in there... I hope. Me and Bin'zin cut our tusks together growin' up. He grew into a strong shaman. Our village needs him, and he is like a brother to me.", progress = "Are the prisoners safe?", completion = "Oh, yes, {name}!\n\nIn one blow, there are more of us and less of dem!\n\nWe best make dem too afraid to ever take Witherbark again.", objectives = "Free 8 Witherbark Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91836] = { id = 91836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respect de Totem", description = "When dey took Bin'zin, de priestess destroyed his totems and gave de shattered remains to her minions--like some grisly memento.\n\nTake de pieces back, one by one if ya have to. Dat disrespect will not stand.", progress = "How goes de lootin'?", completion = "In a world of horrors, we must enjoy de good we feel for causin' dem trouble.\n\nThese pieces will go back where dey belong.\n\nYa played it well, {name}.", objectives = "Collect 40 Totem Remnants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91837] = { id = 91837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Back De Bones", description = "Big thanks for breakin' us free. Some were not so lucky.\n\nBring dey bones back to de Chief, he will know what to do.", objectives = "Collect 8 Bones of de Fallen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91838] = { id = 91838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Vile Diminished", description = "These vile orbs are harvestin' de souls of our people and sendin' dark energy to de Knife Priestess. She's gettin' mighty powerful.\n\nDestroy de orbs so her ritual of death is ruined. With de gift of Shadra, ya will not fail.", progress = "Did ya find all de orbs?", completion = "Do ya sense it? De death energy dat was oozin' about de place feels thin.\n\nIt will take but a breath to end dis ritual for good.", objectives = "Destroy 5 Vile Orbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91839] = { id = 91839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacrifice Denied", completion = "All of this is my own fault. De Vilebranch so close to de village... I shoulda been more aware.\n\nMy mate leapt in de way of a death meant for me. \n\nOne moment I'm angry, then I feel de guilt for it, and de sorrow takes' over.\n\nAt de end of de day, I'm keepin' a strong face for Jin.", objectives = "Check on Bin'zin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91840] = { id = 91840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Will Not Rise", description = "Now's our best shot! We end de sacrifices here! Stoppin' de dark energy has weakened her hold.\n\nThen, you can be de one to bring back her head.\n\nUh, and {name}--no tellin' de chief about me callin' him Big VunVun. He'll be turnin' me into a frog if he hears dat again.", progress = "I am pleased you're takin' my words so literally.", completion = "Ah! My day's gettin' better already! De Witherbark are grateful, {name}.\n\nDak'zor didn't say... nevermind. I don't wanna know.", objectives = "Deliver the head of Knife Priestess Hezzia to Vun'zarah in Witherbark Bluffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91842] = { id = 91842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarm the Dark Horde", description = "The Dark Horde have no love fer their equipment. Look at their weapons! Cracked, rusted, blunt, and bent. Ach!\n\nThe only way they function is by making more shoddy tools to constantly replace the ones they've broken.\n\nIf ye see any of their weapon racks, destroy 'em. Let's see how well they fight without their rusty blades.\n\nA bare-fisted orc is nothing to sneeze at, but it'll further delay any daft plans they've got.", completion = "Did ye destroy their weapons racks?\n\nAye, that'll do. We've bought everyone nearby a few months of peace while they resupply.", objectives = "Destroy 8 Dark Horde Weapon Racks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91843] = { id = 91843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recap: The Harbinger", description = "To understand the story of The War Within, one must first begin with the mysterious entity known as the Harbinger, and how the heroes of Azeroth uncovered the truth...", progress = "Xal'atath was a mysterious foe with ties to the Void. Her presence portended dire things for Azeroth...", completion = "Alleria uncovered the mystery of the Harbinger, revealing Xal'atath. However, it would not be long before the Harbinger made her move.", objectives = "Read along with the Tome of History and learn about the events which sparked The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91844] = { id = 91844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research Promotion: Honorary Chronographer", objectives = "{name}, you have been an excellent assistant with our research. I think you deserve a promotion.\n\nFrom now on, you will be able to take on more research assignments simultaneously.\n\nIt's ironic, isn't it, that we never seem to have enough time. Make good use of your time here. Don't make me regret granting you this power.This quest line will unlock:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91845] = { id = 91845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research Promotion: Senior Executive Chronographer", objectives = "{name}, you have been an excellent assistant with our research. I think you deserve a promotion.\n\nFrom now on, you will be able to take on more research assignments simultaneously.\n\nIt's ironic, isn't it, that we never seem to have enough time. Make good use of your time here. Don't make me regret granting you this power.This quest line will unlock:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91846] = { id = 91846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research Promotion: Principal Chronoquery Investigator", objectives = "{name}, you have been an excellent assistant with our research. I think you deserve a promotion.\n\nFrom now on, you will be able to take on more research assignments simultaneously.\n\nIt's ironic, isn't it, that we never seem to have enough time. Make good use of your time here. Don't make me regret granting you this power.This quest line will unlock:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91847] = { id = 91847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research" }
quests[91848] = { id = 91848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research" }
quests[91849] = { id = 91849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research" }
quests[91854] = { id = 91854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepening Shadows", description = "Champion, I could use your assistance. The natives here in Silvermoon are proving to be less hospitable than we had hoped. \n\nIn their defense, their city is facing down a darkness unlike anything Azeroth has ever faced, so tensions are high.\n\nCan you use your unique perspective and help de-escalate some of the hot spots that are emerging around Silvermoon?", progress = "Tensions are high.", completion = "Well done. That Voidstorm is evoking fear and terror in everyone who sees it, myself included. \n\nBut I chose this life of standing up to evil and spitting in its face. Sadly not everyone had the luxury of that being a choice.", objectives = "De-escalate rising tensions in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91855] = { id = 91855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: K'aresh World Quests", description = "I know now that the heroes of Azeroth venture wherever help is needed. K'aresh is a strange, faraway place, but our allies there need us.\n\nGo there and help them. See what you can do to bring respite to the ethereals and brokers.", progress = "Our allies resist valiantly on a dead and shattered world. I admire them.", completion = "You are a credit to heroes everywhere. Thank you.", objectives = "Complete World Quests in K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91863] = { id = 91863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My First Home", description = "Welcome to the neighborhood! Feel free to explore and have a look at the plots available.\n\nSpeak to the steward to learn more about the process of becoming a homeowner or if you wish to create your own neighborhood.", progress = "Have you found your forever home?", completion = "Congratulations on acquiring your new house. We know you'll be very happy here and we look forward to seeing you around the neighborhood.", objectives = "Familiarize yourself with the neighborhood and its residents, and then find a place to build a house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91864] = { id = 91864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recap: Fractured Visions", description = "All across Azeroth, many were having visions of a Radiant Song. Efforts to understand what seemed to be a warning centered on the heroes in Dalaran.", completion = "The island of Khaz Algar figured into Xal'atath's plans, and it was up to the champions of Azeroth to thwart them.", objectives = "Consult the Tome of History to learn about the fate of Dalaran in The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91865] = { id = 91865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch Up: Khaz Algar", description = "The Earthen of Khaz Algar eventually welcomed the outsiders into their land, but all was not well with them. Divisions had grown among their people. To unravel Xal'atath's plot with the Nerubians, the Champions would have to address these issues.", objectives = "Consult the Tome of History to learn about the events in Khaz Algar in The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91866] = { id = 91866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch Up: The Ringing Deeps", description = "The Champions travel with Brinthe of the Earthen and Moira, Dagran and Magni Bronzebeard to the Ringing deeps. There they find not all is well as a mysterious affliction has touched some of the workers.", objectives = "Consult the Tome of History to learn about the events in the Ringing Deeps in The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91867] = { id = 91867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch Up: Hallowfall", description = "King Anduin Wrynn, Alleria and the Champions travel deeper into Azeroth, arriving at a place known as Hallowfall. It quickly become apparent that this place has also been touched by the machinations of Xal'atath.", objectives = "Consult the Tome of History to learn about the events in Hallowfall in The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91868] = { id = 91868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recap: Shadowy Pursuits", description = "King Anduin Wrynn, Alleria, and the champions travel deeper into Azeroth, arriving at a place known as Hallowfall. It quickly becomes apparent that this place has also been touched by the machinations of Xal'atath.", completion = "With a few select allies, Anduin, Alleria, and the champions escaped Xal'atath's clutches, but this would not be the last encounter with her...", objectives = "Consult the Tome of History to learn about the events in Hallowfall and Azj-Kahet in The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91869] = { id = 91869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch Up: A Light in the Dark", description = "The War Within continued on Khaz Algar as the peoples of the land began to unite against Xal'atath and her Dark Heart.", objectives = "Consult the Tome of History to learn about the events in The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91871] = { id = 91871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recap: The Dark Heart", description = "The champions and Alleria were invited to Undermine by Gazlowe as the peoples of Khaz Algar and beyond began to unite against Xal'atath and her Dark Heart.", progress = "Dimensius was defeated and Azeroth was saved from his threat, yet there was a cost.", completion = "This is the conclusion of The War Within, but it is not the last time we'll see Xal'atath or the Dark Heart...", objectives = "Consult the Tome of History to learn about the events in Undermine and K'aresh in The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91872] = { id = 91872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Former Rootwarden", completion = "I lived far longer before I became Rootwarden than after.\n\nYet Teldrassil will always be what defines my life.", objectives = "Meet Hagar at the Shrine of Ages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91873] = { id = 91873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buffer Zone", description = "At this shrine, I have worked to gather roots that seem to still have the possibility of life within them. They are each greatly damaged, some more than others. My hope is some might recover, with enough time and enough care. In that way, I honor the great tree's memory.\n\nFor that to be possible, though, we have to keep them safe from the hazards of Harandar.\n\nPlease be sure that nothing nearby threatens them.", completion = "Thank you for helping to protect what may still live of Teldrassil.\n\nIt may be that nothing remains. Some of these roots still smolder.\n\nYet I vowed to serve as Rootwarden, and I will not fail a second time, if there is any hope. I choose each day to believe there may be--that Teldrassil could bloom again.\n\nThough I may only be preserving her memory.", objectives = "Protect the shrine from local wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91874] = { id = 91874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flare Up", completion = "{name}, the smell of smoke fills me with the same dread I felt on that terrible day.\n\nThere is much heat still trapped within the largest roots, and in the right circumstances, the burning begins anew.\n\nIf we have any hope of seeing the roots restored one day, we have to be vigilant against even small fires.\n\nAt best, they undo our work, but at worst, they could spread to consume what remains.\n\nThank you for helping me keep watch.", objectives = "Fly near the flames on the roots of Teldrassil to douse them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91875] = { id = 91875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Remedy", description = "If we ever hope to see new growth, Teldrassil's roots needs a great deal of special attention.\n\nThe source of this stream is one of the great roots. The water carries ash, which I believe still contains the tree's essence.\n\nThe stalkers in the stream carry a mixture of that ash and slime from their tendrils--a very potent mixture.\n\nBring me as much of it as you can carry, and I will combine it with reagents I've gathered. Then we'll be ready to apply it to the roots.", progress = "Do you have the rejuvenating mud I asked for?", completion = "This will do nicely, for today. Just give me a moment to mix...\n\n{name}, do you smell smoke?", objectives = "Gather 8 clumps of Verdant Stalker Sludge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91876] = { id = 91876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending Hope", completion = "Thank you, {name}, for your help. Because of you, I was able to keep up my routines even with those fires.\n\nPerhaps one day, we might see a sprout--even if it takes many years.\n\nAnd I shall be ever ready to resume my duties as Rootwarden, should hope bloom.", objectives = "Apply Hagar's salve to 12 Withered Roots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91884] = { id = 91884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Illusion of Motion", description = "You! Have YOU seen them?\n\nI've been tasked to investigate some of our scouts that have gone missing. My reconnaissance had come up empty until recently.\n\nNow I've been catching glimpses of the missing scouts, but... they appear formed of pure Void energy.\n\nEach time I chase the figures, they lead me further and further before disappearing!\n\nThe others think I'm crazy. You haven't seen anything like that, have you?", completion = "Do you see them? Their cries for help... echoing... all around...", objectives = "Investigate the mysterious figures Nefina has seen around Locus Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91885] = { id = 91885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drain You", description = "Do you... see...? They follow... They plead... for help...\n\n<The voidwalker strains and shudders as it tries to communicate.>\n\nToo weak... too starving...\n\n<It feebly hands you a shard of dark matter.>\n\nThis... will feed me... then together... we find the missing elves...", completion = "I am better now... stable, but a fatigue still clings to me.\n\nIf we're to find your scouts, I will need your help.", objectives = "Slay Voidstorm wildlife and use the Void Splinter to feed the Starving Voidwalker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91886] = { id = 91886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voices of Omens", description = "The voices of your elven allies rattle inside my head.\n\nI know of a way we can find them. There is a way to locate missing things... using old domanaar scanning devices.\n\nBut they require immense energy to function. Together, we can use these devices to focus the images of your lost friends. Their cries for help will become clearer, and then you can find them.\n\nCome. Lend me your strength.", completion = "The voidwalker's been feeding on us all the while... but why the misdirection? Whatever the case may be, it's time to end this.\n\nAnd this time, WE will have the element of surprise.", objectives = "Help the Sentient Voidwalker power Domanaar Scrystones to help locate the missing scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91887] = { id = 91887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dominion of Deceit", description = "We were right to be cautious. The threats we've found here in the Voidstorm are corrupting and irredeemable.\n\nThis voidwalker's meticulous deceptions are unusual... I can't help but wonder why it would go through all the trouble. \n\n<She looks up at you from weary, withered eyes.>\n\nBut I'm too weak to go on. It really did a number on me. You have the upper hand now! It thinks you're walking into its trap.\n\nWalk in with weapons drawn and spells ready!", completion = "The creature ensnared so many of us in its web of lies.\n\nWe must remain steadfast. The Voidstorm is a terribly hostile place.", objectives = "Slay the Deceitful Voidwalker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91918] = { id = 91918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Measure Once, Cut Twice", description = "We've done well to see those deserters to safety, but don't fool yourself into thinking we've freed them all.\n\nI've heard whispers of a place they use to break those whose loyalty is in question. The location isn't common knowledge, but I know where to start looking.\n\nIf we're quick, we might find others before the cult decides they're too great a risk to keep alive.\n\nMeet me near the site. Keep your blades sharp and your steps light.", completion = "That's all of them. Good work.", objectives = "Rescue the remaining Twilight's Blade Deserters from the Twilight Crypts delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91927] = { id = 91927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ooze Booting" }
quests[91928] = { id = 91928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's For Lunch?", description = "My Shadowtrade Mercenaries will fight for Stormarion Cores, no questions asked, but they do get hungry also!\n\nFood is quite scarce here, so we need supplies!\n\nTake a mercenary out with you and find some food for them to eat. I'll make it worth your while!", objectives = "Slay Trigores for 3 Trigore Flanks and collect 20 Shadow-Grown Berries that grow in the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91929] = { id = 91929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's For Lunch?", description = "My Shadowtrade Mercenaries will fight for Stormarion Cores, no questions asked, but they do get hungry also!\n\nFood is quite scarce here, so we need supplies!\n\nTake a mercenary out with you and find some food for them to eat. I'll make it worth your while!", objectives = "Slay Unstable Oozeling for 12 Void Malgrease and collect 3 Domanaar Microwell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91930] = { id = 91930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abundant Lands", description = "De loa have reunited with us forest trolls, and de land reacts with glorious bounty!\n\nDo ya wish to take part? Then go north, and meet me at de entrance to Loaknit Den.\n\nThere I will introduce ya to prosperity and plentitude like ya never seen...", completion = "It is time to learn from de master himself.", objectives = "Speak with Chel the Chip at Loaknit Den in Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91932] = { id = 91932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abundant Awakening", description = "De Loa of Abundance accepts everyone, and everyone de Loa of Abundance accepts is granted de privilege of learnin' how best to serve abundance.\n\nSpeak with his glorious visage and become a fellow acolyte.", progress = "Do not fear. I am indeed the finest judge of your every action and choice.", completion = "Quite acceptable!\n\nYou may yet prove a glorious addition to the acolytes of abundance.", objectives = "Speak with the Loa of Abundance and learn the ways of harvesting abundance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91933] = { id = 91933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abundant Honor", description = "On to the next phase of your education: mercantilism!\n\nImagine yourself, offering the bounty of endless harvest to my glorious self, and reaping the abundant rewards I bestow upon you in kind.\n\nNow let us put that beauteous vision into practice! \n\nI will grant you a minute portion of unalloyed abundance. You, in turn, shall trade it to your fellow acolyte for one of many premium goods.", progress = "There are few things amongst mortals or gods that cannot be viewed through the lens of trade.\n\nSome of us are simply... less coy about that truth than others are.", completion = "Ah! I see you are already well-versed in the art of barter and trade!", objectives = "Purchase an Abundant Beacon from Chel the Chip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91937] = { id = 91937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portraits in the Vale" }
quests[91954] = { id = 91954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freezing Over", objectives = "We noticed this large creeper tracking you out in the wastes, but when it emerged it made no aggressive moves whatsoever. Judging by its reaction to your arrival, I believe you're the one its been looking for. You're becoming quite popular, no?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91955] = { id = 91955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Between Us", description = "The artifact we snatched from the timeline earlier was replaced with a simulacrum so none would notice the true artifact's absence.\n\nSuch a wealth of infinite energy should not be abandoned so readily. You should seek it out and reclaim it.\n\nOnce you have recovered the simulacrum you can scrap it for an embarassing sum of bronze and infinite power.", completion = "Success!\n\nIt's almost a shame to destroy such a beautiful replica.\n\nBut you have the real thing, so I say scrap it and rejoice at the bounty of beautiful bronze!", objectives = "Retrieve the Curious Simulacrum left in place of your \"borrowed\" artifact weapon by completing your artifact weapon's acquisition storyline as part of your Order Hall campaign.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91958] = { id = 91958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den of Nalorakk: Unforgiven", description = "Nalorakk is de Loa of War. His trial must be a battle!\n\nThere would be no greater death for an Amani than to die in combat against de Loa of War. No greater thrill than fightin' him.\n\nDoes it not make your blood pump faster and harder in your veins, hash'ura?\n\n<Zul'jarra lets out a feral howl and laughs.>\n\nCome. Meet me at Nalorakk's Prowl and we will sit at his fire and face our last trial--together.", progress = "De final trial is at hand.", completion = "Heh.\n\nWe won against Nalorakk. We passed de last trial.\n\nMy tribe will sing songs and tell stories of dis day for generations.", objectives = "Complete the Den of Nalorakk dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91963] = { id = 91963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Amok", description = "I've heard from the other scouts about that metal--the shadowgraft. The domanaar use it to enforce their control over others.\n\nI have to imagine that there's someone holding the reins still. Maybe it's Xal'atath, or maybe someone else. Gather pieces of their shadowgraft and maybe we can make sense of who.", progress = "Have you gathered enough for us to study?", completion = "There are multiple styles of shadowgraft in the samples you collected. It seems like there are multiple domanaar vying for control of the power vacuum left here in Obscurion. Xal'atath must not be in command here.\n\nWe'll take care of this one foe and let the rest of the domanaar fight among themselves.", objectives = "Gather Shadowgraft from foes at Obscurion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91966] = { id = 91966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltheril's Soiree" }
